import base64

import numpy as np
import pytest

from colab_viz.domains.d7_visualization.readers import describe_field, read_field


_GRIB1 = ""
_GRIB2 = ""


@pytest.mark.parametrize(("name", "payload"), (("fixture.grib1", _GRIB1), ("fixture.grib2", _GRIB2)))
def test_grib_editions_keep_time_and_level_selections_distinct(tmp_path, name, payload):
    path = tmp_path / name
    path.write_bytes(base64.b64decode(payload))
    fmt, variables, instants = describe_field(path)
    assert fmt == "GRIB" and instants == []
    assert len(variables) == 4 and len(set(variables)) == 4
    assert len({v.split("|")[1] for v in variables}) == 2
    assert len({v.split("|")[2] for v in variables}) == 2
    means = [float(np.nanmean(read_field(path, variable=v)[1].values)) for v in variables]
    assert means == pytest.approx([5.5, 25.5, 45.5, 65.5], abs=1e-4)
